def marker_bits_4x4(marker_id: int) -> List[List[int]]:
    w = DICT_4X4_250[int(marker_id) % len(DICT_4X4_250)]
    bits: List[List[int]] = []
    for r in range(4):
        row = []
        for c in range(4):
            shift = 15 - (r * 4 + c)
            row.append((w >> shift) & 1)
        bits.append(row)
    return bits

